func main() {
    if len(os.Args) < 2 {
        fmt.Fprintln(os.Stderr, "no args provided")
        return
    }
    switch os.Args[1] {
    case "help":
        printHelp()
    case "version":
        fmt.Printf("go-critic version: %s\n", version)
    case "doc":
        os.Exit(runDoc(os.Args[2:]))
    case "check":
        os.Exit(runCheck(os.Args[2:]))
    default:
        cmd := os.Args[1]
        if s := suggestCommand(cmd); s != "" {
            fmt.Printf("%q unknown command, did you mean %q?\n", cmd, s)
        } else {
            fmt.Printf("%q unknown command\n", cmd)
        }
        fmt.Println("Run \"go-critic help\" for usage.")
        fmt.Println()
        fmt.Fprintf(os.Stderr, "no such command %q\n", cmd)
    }
}

func printHelp() {
    fmt.Print(`Usage:

    go-critic <command> [arguments...]

The commands are:

    check             run linter over specified targets
    doc               get installed checkers documentation
    help              shows help message
    version           shows version of the application

Version: v0.0.0-SNAPSHOT
`)
}

func suggestCommand(cmd string) string {
    best, dist := "", 100
    for _, c := range []string{"check", "doc", "help", "version"} {
        d := editDistance(cmd, c)
        if d < dist { best, dist = c, d }
    }
    if dist <= 2 { return best }
    return ""
}

func editDistance(a, b string) int {
    da := []rune(a); db := []rune(b)
    dp := make([]int, len(db)+1)
    for j := range dp { dp[j] = j }
    for i, ca := range da {
        prev := dp[0]
        dp[0] = i+1
        for j, cb := range db {
            old := dp[j+1]
            cost := 0
            if ca != cb { cost = 1 }
            v := prev + cost
            if dp[j]+1 < v { v = dp[j]+1 }
            if old+1 < v { v = old+1 }
            dp[j+1] = v
            prev = old
        }
    }
    return dp[len(db)]
}

func runDoc(args []string) int {
    fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    fs.Usage = func() { fmt.Fprintln(os.Stderr, "Usage of go-critic:") }
    if err := fs.Parse(args); err != nil {
        fmt.Fprintln(os.Stderr, err)
        return 0
    }
    rest := fs.Args()
    if len(rest) > 1 {
        fmt.Fprintln(os.Stderr, "expected 0 or 1 positional arguments")
        return 1
    }
    if len(rest) == 0 {
        for _, name := range checkerOrder {
            fmt.Printf("%s [%s]\n", name, strings.Join(checkerTags[name], " "))
        }
        return 0
    }
    name := rest[0]
    if s, ok := docData[name]; ok {
        fmt.Print(s)
        return 0
    }
    fmt.Fprintf(os.Stderr, "checker with name %q not found\n", name)
    return 1
}

type checkConfig struct {
    enable, disable string
    enableAll bool
    checkGenerated bool
    checkTests bool
    exitCode int
    verbose bool
    captParamsOnly bool
    shorterErrLocation bool
    goVersion string
}

func runCheck(args []string) int {
    cfg := checkConfig{enable: defaultEnable, checkTests: true, exitCode: 1, captParamsOnly: true, shorterErrLocation: true}
    fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    fs.BoolVar(&cfg.captParamsOnly, "@captLocal.paramsOnly", true, "whether to restrict checker to params only")
    fs.Int("@commentedOutCode.minLength", 15, "min length of the comment that triggers a warning")
    fs.Bool("@elseif.skipBalanced", true, "whether to skip balanced if-else pairs")
    fs.Int("@hugeParam.sizeThreshold", 80, "size in bytes that makes the warning trigger")
    fs.Int("@ifElseChain.minThreshold", 2, "min number of if-else blocks that makes the warning trigger")
    fs.Int("@nestingReduce.bodyWidth", 5, "min number of statements inside a branch to trigger a warning")
    fs.Int("@rangeExprCopy.sizeThreshold", 512, "size in bytes that makes the warning trigger")
    fs.Bool("@rangeExprCopy.skipTestFuncs", true, "whether to check test functions")
    fs.Int("@rangeValCopy.sizeThreshold", 128, "size in bytes that makes the warning trigger")
    fs.Bool("@rangeValCopy.skipTestFuncs", true, "whether to check test functions")
    fs.String("@ruleguard.debug", "", "enable debug for the specified named rules group")
    fs.String("@ruleguard.disable", "", "comma-separated list of disabled groups or skip empty to enable everything")
    fs.String("@ruleguard.enable", "<all>", "comma-separated list of enabled groups or skip empty to enable everything")
    fs.String("@ruleguard.failOn", "", "Determines the behavior when an error occurs while parsing ruleguard files.\nIf flag is not set, log error and skip rule files that contain an error.\nIf flag is set, the value must be a comma-separated list of error conditions.\n* 'import': rule refers to a package that cannot be loaded.\n* 'dsl':    gorule file does not comply with the ruleguard DSL.")
    fs.Bool("@ruleguard.failOnError", false, "deprecated, use failOn param; if set to true, identical to failOn='all', otherwise failOn=''")
    fs.String("@ruleguard.rules", "", "comma-separated list of gorule file paths. Glob patterns such as 'rules-*.go' may be specified")
    fs.Int("@tooManyResultsChecker.maxResults", 5, "maximum number of results")
    fs.Bool("@truncateCmp.skipArchDependent", true, "whether to skip int/uint/uintptr types")
    fs.Bool("@underef.skipRecvDeref", true, "whether to skip (*x).method() calls where x is a pointer receiver")
    fs.Bool("@unnamedResult.checkExported", false, "whether to check exported functions")
    fs.BoolVar(&cfg.checkGenerated, "checkGenerated", false, "whether to check generated files")
    fs.BoolVar(&cfg.checkTests, "checkTests", true, "whether to check test files")
    fs.Int("concurrency", runtime.GOMAXPROCS(0), "how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
    fs.String("cpuprofile", "", "write CPU profile to the specified file")
    fs.StringVar(&cfg.disable, "disable", "", "comma-separated list of checkers to be disabled. Can include #tags")
    fs.StringVar(&cfg.enable, "enable", defaultEnable, "comma-separated list of enabled checkers. Can include #tags")
    fs.BoolVar(&cfg.enableAll, "enableAll", false, "identical to -enable with all checkers listed. If true, -enable is ignored")
    fs.IntVar(&cfg.exitCode, "exitCode", 1, "exit code to be used when lint issues are found")
    fs.StringVar(&cfg.goVersion, "go", "", "select the Go version to target. Leave as string for the latest")
    fs.String("memprofile", "", "write memory profile to the specified file")
    fs.BoolVar(&cfg.shorterErrLocation, "shorterErrLocation", true, "whether to replace error location prefix with $GOROOT and $GOPATH")
    fs.BoolVar(&cfg.verbose, "v", false, "whether to print output useful during linter debugging")
    if err := fs.Parse(args); err != nil {
        fmt.Fprintf(os.Stderr, "parse args: %v\n", err)
        return 1
    }

    selected := selectCheckers(cfg)
    if len(selected) == 0 {
        fmt.Fprintln(os.Stderr, "init checkers: empty checkers set selected")
        return 1
    }
    if cfg.verbose {
        for _, name := range checkerOrder {
            if !selected[name] { fmt.Fprintf(os.Stderr, "\tdebug: %s: not enabled by name or tag (-enable)\n", name) }
        }
        for _, name := range checkerOrder {
            if selected[name] { fmt.Fprintf(os.Stderr, "\tdebug: %s is enabled\n", name) }
        }
    }

    files := collectFiles(fs.Args(), cfg)
    if cfg.verbose {
        for _, f := range files { fmt.Fprintf(os.Stderr, "\tdebug: checking \"command-line-arguments\" package (1 files)\n"); _ = f }
    }
    var diags []diag
    for _, path := range files {
        p, err := parseSource(path)
        if err != nil { continue }
        if !cfg.checkGenerated && p.generated { continue }
        for _, name := range checkerOrder {
            if !selected[name] { continue }
            diags = append(diags, runChecker(name, p, cfg)...)
        }
    }
    // Diagnostics are naturally ordered by checker then file. Keep source order inside one checker.
    if len(diags) != 0 {
        for _, d := range diags { fmt.Fprintf(os.Stderr, "%s:%d:%d: %s: %s\n", d.file, d.line, d.col, d.checker, d.msg) }
        if cfg.exitCode == 0 { return 0 }
        return cfg.exitCode
    }
    return 0
}

func selectCheckers(cfg checkConfig) map[string]bool {
    selected := map[string]bool{}
    if cfg.enableAll {
        for _, name := range checkerOrder { selected[name] = true }
    } else {
        addTokens(selected, cfg.enable, true)
    }
    addTokens(selected, cfg.disable, false)
    return selected
}
func addTokens(m map[string]bool, s string, add bool) {
    for _, tok := range strings.Split(s, ",") {
        tok = strings.TrimSpace(tok)
        if tok == "" { continue }
        if strings.HasPrefix(tok, "#") {
            tag := strings.TrimPrefix(tok, "#")
            for _, name := range checkerOrder {
                for _, t := range checkerTags[name] { if t == tag { if add {m[name]=true} else {delete(m,name)} } }
            }
        } else if _, ok := checkerTags[tok]; ok {
            if add { m[tok]=true } else { delete(m, tok) }
        }
    }
}

func collectFiles(args []string, cfg checkConfig) []string {
    var files []string
    for _, a := range args {
        if strings.HasSuffix(a, ".go") {
            if !cfg.checkTests && strings.HasSuffix(a, "_test.go") { continue }
            if st, err := os.Stat(a); err == nil && !st.IsDir() { files = append(files, a) }
        }
    }
    return files
}

type parsedFile struct { path string; src []byte; fset *token.FileSet; file *ast.File; generated bool }
type diag struct { checker string; file string; line, col int; msg string }

func parseSource(path string) (*parsedFile, error) {
    src, err := os.ReadFile(path); if err != nil { return nil, err }
    fset := token.NewFileSet()
    file, err := parser.ParseFile(fset, path, src, parser.ParseComments)
    if err != nil { return nil, err }
    generated := false
    for _, cg := range file.Comments {
        for _, c := range cg.List {
            if strings.Contains(c.Text, "Code generated ") && strings.Contains(c.Text, "DO NOT EDIT.") { generated = true }
        }
    }
    return &parsedFile{path:path, src:src, fset:fset, file:file, generated:generated}, nil
}
func (p *parsedFile) pos(pos token.Pos) (string,int,int) { x := p.fset.Position(pos); return x.Filename,x.Line,x.Column }
func (p *parsedFile) diag(checker string, pos token.Pos, msg string) diag { f,l,c := p.pos(pos); return diag{checker:checker,file:f,line:l,col:c,msg:msg} }
func (p *parsedFile) text(n ast.Node) string {
    if n == nil { return "" }
    a := p.fset.Position(n.Pos()).Offset; b := p.fset.Position(n.End()).Offset
    if a < 0 || b < a || b > len(p.src) { return "" }
    return strings.TrimSpace(string(p.src[a:b]))
}

func runChecker(name string, p *parsedFile, cfg checkConfig) []diag {
    switch name {
    case "appendAssign": return checkAppendAssign(p)
    case "argOrder": return checkArgOrder(p)
    case "assignOp": return checkAssignOp(p)
    case "badCall": return checkBadCall(p)
    case "badCond": return checkBadCond(p)
    case "captLocal": return checkCaptLocal(p, cfg)
    case "codegenComment": return checkCodegenComment(p)
    case "commentFormatting": return checkCommentFormatting(p)
    case "defaultCaseOrder": return checkDefaultCaseOrder(p)
    case "deprecatedComment": return checkDeprecatedComment(p)
    case "dupArg": return checkDupArg(p)
    case "dupBranchBody": return checkDupBranchBody(p)
    case "dupCase": return checkDupCase(p)
    case "dupSubExpr": return checkDupSubExpr(p)
    case "elseif": return checkElseIf(p)
    case "exitAfterDefer": return checkExitAfterDefer(p)
    case "flagDeref": return checkFlagDeref(p)
    case "flagName": return checkFlagName(p)
    case "ifElseChain": return checkIfElseChain(p)
    case "mapKey": return checkMapKey(p)
    case "newDeref": return checkNewDeref(p)
    case "offBy1": return checkOffBy1(p)
    case "regexpMust": return checkRegexpMust(p)
    case "singleCaseSwitch": return checkSingleCaseSwitch(p)
    case "sloppyLen": return checkSloppyLen(p)
    case "sloppyTypeAssert": return checkSloppyTypeAssert(p)
    case "switchTrue": return checkSwitchTrue(p)
    case "typeSwitchVar": return checkTypeSwitchVar(p)
    case "underef": return checkUnderef(p)
    case "unlambda": return checkUnlambda(p)
    case "unslice": return checkUnslice(p)
    case "wrapperFunc": return checkWrapperFunc(p)
    case "appendCombine": return checkAppendCombine(p)
    case "badSorting": return checkBadSorting(p)
    case "boolExprSimplify": return checkBoolExprSimplify(p)
    case "builtinShadow", "importShadow": return checkShadow(p, name)
    case "commentedOutImport": return checkCommentedOutImport(p)
    case "deferInLoop": return checkDeferInLoop(p)
    case "deferUnlambda": return checkDeferUnlambda(p)
    case "docStub": return checkDocStub(p)
    case "dupImport": return checkDupImport(p)
    case "dynamicFmtString": return checkDynamicFmtString(p)
    case "emptyDecl": return checkEmptyDecl(p)
    case "emptyStringTest": return checkEmptyStringTest(p)
    case "equalFold": return checkEqualFold(p)
    case "externalErrorReassign": return checkExternalErrorReassign(p)
    case "filepathJoin": return checkFilepathJoin(p)
    case "hexLiteral": return checkHexLiteral(p)
    case "httpNoBody": return checkHTTPNoBody(p)
    case "methodExprCall": return checkMethodExprCall(p)
    case "octalLiteral": return checkOctalLiteral(p)
    case "paramTypeCombine": return checkParamTypeCombine(p)
    case "preferFilepathJoin": return checkPreferFilepathJoin(p)
    case "preferStringWriter": return checkPreferStringWriter(p)
    case "preferWriteByte": return checkPreferWriteByte(p)
    case "rangeAppendAll": return checkRangeAppendAll(p)
    case "redundantSprint": return checkRedundantSprint(p)
    case "returnAfterHttpError": return checkReturnAfterHTTPError(p)
    case "sloppyReassign": return checkSloppyReassign(p)
    case "stringsCompare": return checkStringsCompare(p)
    case "timeExprSimplify": return checkTimeExprSimplify(p)
    case "todoCommentWithoutDetail": return checkTODOComment(p)
    case "tooManyResultsChecker": return checkTooManyResults(p)
    case "typeUnparen": return checkTypeUnparen(p)
    case "unnecessaryBlock": return checkUnnecessaryBlock(p)
    case "unnecessaryDefer": return checkUnnecessaryDefer(p)
    case "whyNoLint": return checkWhyNoLint(p)
    case "yodaStyleExpr": return checkYoda(p)
    case "zeroByteRepeat": return checkZeroByteRepeat(p)
    }
    return nil
}

func inspect(p *parsedFile, fn func(ast.Node)) { ast.Inspect(p.file, func(n ast.Node) bool { if n != nil { fn(n) }; return true }) }
func isIdent(e ast.Expr, name string) bool { id, ok := e.(*ast.Ident); return ok && id.Name == name }
func selName(e ast.Expr) string { if s, ok := e.(*ast.SelectorExpr); ok { return pTextX(s.X)+"."+s.Sel.Name }; return "" }
func pTextX(e ast.Expr) string { switch x:=e.(type) { case *ast.Ident: return x.Name; case *ast.SelectorExpr: return pTextX(x.X)+"."+x.Sel.Name }; return "" }
func callName(c *ast.CallExpr) string { return selName(c.Fun) }
func strLit(e ast.Expr) (string,bool) { bl, ok := e.(*ast.BasicLit); if !ok || bl.Kind != token.STRING { return "", false }; s, err := strconv.Unquote(bl.Value); if err != nil { return "", false }; return s, true }
func intLit(e ast.Expr) (int64,bool) { bl, ok := e.(*ast.BasicLit); if !ok || bl.Kind != token.INT { return 0,false }; v,err:=strconv.ParseInt(bl.Value,0,64); return v,err==nil }
func exprEq(p *parsedFile, a,b ast.Expr) bool { return p.text(a) == p.text(b) }

func checkAppendAssign(p *parsedFile) (out []diag) { inspect(p, func(n ast.Node){ as,ok:=n.(*ast.AssignStmt); if !ok || len(as.Lhs)!=len(as.Rhs){return}; for i,r:=range as.Rhs{ c,ok:=r.(*ast.CallExpr); if !ok || !isIdent(c.Fun,"append") || len(c.Args)==0{return}; if p.text(as.Lhs[i])!=p.text(c.Args[0]) { out=append(out,p.diag("appendAssign", c.Pos(), "append result not assigned to the same slice")) } } }); return }
func checkArgOrder(p *parsedFile) (out []diag) { inspect(p, func(n ast.Node){ c,ok:=n.(*ast.CallExpr); if !ok || len(c.Args)<2{return}; name:=callName(c); if name=="strings.HasPrefix"||name=="strings.HasSuffix"||name=="strings.Contains"||name=="bytes.HasPrefix"||name=="bytes.HasSuffix"||name=="bytes.Contains"{ if _,ok:=strLit(c.Args[0]); ok { if _,ok2:=strLit(c.Args[1]); !ok2 { out=append(out,p.diag("argOrder", c.Pos(), fmt.Sprintf("%s and %s arguments order looks reversed", p.text(c.Args[0]), p.text(c.Args[1])))) } } } }); return }
func checkAssignOp(p *parsedFile) (out []diag) { inspect(p, func(n ast.Node){ as,ok:=n.(*ast.AssignStmt); if !ok||as.Tok!=token.ASSIGN||len(as.Lhs)!=1||len(as.Rhs)!=1{return}; b,ok:=as.Rhs[0].(*ast.BinaryExpr); if !ok{return}; lhs:=p.text(as.Lhs[0]); var rhs string; if p.text(b.X)==lhs { rhs=p.text(b.Y) } else if (b.Op==token.ADD||b.Op==token.MUL||b.Op==token.AND||b.Op==token.OR||b.Op==token.XOR) && p.text(b.Y)==lhs { rhs=p.text(b.X) } else { return }; repl:=""; if (b.Op==token.ADD||b.Op==token.SUB) && rhs=="1" { if b.Op==token.ADD { repl=lhs+"++" } else { repl=lhs+"--" } } else { repl=lhs+" "+b.Op.String()+"= "+rhs }; out=append(out,p.diag("assignOp", as.Pos(), fmt.Sprintf("replace `%s` with `%s`", p.text(as), repl))) }); return }
func checkBadCall(p *parsedFile) (out []diag) { inspect(p, func(n ast.Node){ c,ok:=n.(*ast.CallExpr); if !ok{return}; if isIdent(c.Fun,"append")&&len(c.Args)==1{ out=append(out,p.diag("badCall", c.Pos(), "no-op append call, probably missing arguments")) }; name:=callName(c); if (name=="strings.Replace"||name=="bytes.Replace")&&len(c.Args)>=4{ if v,ok:=intLit(c.Args[3]); ok&&v==0{ out=append(out,p.diag("badCall", c.Args[3].Pos(), "suspicious arg 0, probably meant -1")) } } }); return }
func checkBadCond(p *parsedFile) (out []diag) { inspect(p, func(n ast.Node){ f,ok:=n.(*ast.ForStmt); if !ok||f.Cond==nil{return}; b,ok:=f.Cond.(*ast.BinaryExpr); if !ok{return}; if b.Op==token.GTR||b.Op==token.GEQ{ out=append(out,p.diag("badCond", f.Pos(), fmt.Sprintf("`%s` in loop; probably meant `%s < %s`?", p.text(b), p.text(b.X), p.text(b.Y)))) } }); return }
func checkCaptLocal(p *parsedFile,cfg checkConfig)(out []diag){ checkField:=func(fl *ast.FieldList){ if fl==nil{return}; for _,f:=range fl.List{ for _,id:=range f.Names{ if id.Name!=""&&isCapitalized(id.Name){ out=append(out,p.diag("captLocal", id.Pos(), fmt.Sprintf("`%s' should not be capitalized", id.Name))) } } } }; for _,d:=range p.file.Decls{ if fn,ok:=d.(*ast.FuncDecl); ok{ checkField(fn.Type.Params); checkField(fn.Type.Results) } }; if !cfg.captParamsOnly{ inspect(p,func(n ast.Node){ if as,ok:=n.(*ast.AssignStmt); ok&&as.Tok==token.DEFINE{ for _,e:=range as.Lhs{ if id,ok:=e.(*ast.Ident); ok&&isCapitalized(id.Name){ out=append(out,p.diag("captLocal", id.Pos(), fmt.Sprintf("`%s' should not be capitalized", id.Name))) } } } })}; return }
func isCapitalized(s string) bool { if s=="" {return false}; c:=s[0]; return c>='A'&&c<='Z' }
func checkCodegenComment(p *parsedFile)(out []diag){ re:=regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`); for _,cg:=range p.file.Comments{ for _,c:=range cg.List{ low:=strings.ToLower(c.Text); if strings.Contains(low,"generated")&&strings.Contains(low,"file")&&!re.MatchString(c.Text){ out=append(out,p.diag("codegenComment", c.Pos(), "comment should match `Code generated .* DO NOT EDIT.` regexp")) } } }; return }
func checkCommentFormatting(p *parsedFile)(out []diag){ for _,cg:=range p.file.Comments{ for _,c:=range cg.List{ t:=c.Text; if strings.HasPrefix(t,"//")&&!strings.HasPrefix(t,"// ")&&!strings.HasPrefix(t,"///")&&!strings.HasPrefix(t,"//go:")&&!strings.HasPrefix(t,"//line")&&len(t)>2{ ch:=t[2]; if ch!=' '&&ch!='\t'&&ch!='/'&&ch!=':'{ out=append(out,p.diag("commentFormatting", c.Pos(), "put a space between `//` and comment text")) } } } }; return }
func checkDefaultCaseOrder(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ var list []*ast.CaseClause; switch x:=n.(type){case *ast.SwitchStmt: list=x.Body.List; case *ast.TypeSwitchStmt: list=x.Body.List}; if len(list)<3{return}; for i,cc:=range list{ if cc.List==nil && i!=0 && i!=len(list)-1{ out=append(out,p.diag("defaultCaseOrder", cc.Case, "consider to make `default` case as first or as last case")) } } }); return }
func checkDeprecatedComment(p *parsedFile)(out []diag){ for _,d:=range p.file.Decls{ var doc *ast.CommentGroup; if gd,ok:=d.(*ast.GenDecl); ok{doc=gd.Doc}; if fd,ok:=d.(*ast.FuncDecl); ok{doc=fd.Doc}; if doc==nil{continue}; for _,c:=range doc.List{ t:=strings.TrimSpace(strings.TrimPrefix(c.Text,"//")); if strings.HasPrefix(t,"Deprecated")&&!strings.HasPrefix(t,"Deprecated:"){ out=append(out,p.diag("deprecatedComment", c.Pos(), "the proper format is `Deprecated: <text>`")) } } }; return }
func checkDupArg(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ c,ok:=n.(*ast.CallExpr); if !ok||len(c.Args)<2{return}; name:=p.text(c.Fun); if (name=="copy"||name=="append"||strings.HasSuffix(name,".Copy"))&&exprEq(p,c.Args[0],c.Args[1]){ out=append(out,p.diag("dupArg", c.Pos(), fmt.Sprintf("suspicious duplicated args in %s", p.text(c)))) } }); return }
func checkDupBranchBody(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ ifs,ok:=n.(*ast.IfStmt); if !ok{return}; eb,ok:=ifs.Else.(*ast.BlockStmt); if !ok{return}; if strings.TrimSpace(p.text(ifs.Body))==strings.TrimSpace(p.text(eb)){ out=append(out,p.diag("dupBranchBody", ifs.Pos(), "both branches in if statement have same body")) } }); return }
func checkDupCase(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ var list []*ast.CaseClause; switch x:=n.(type){case *ast.SwitchStmt: list=x.Body.List; case *ast.TypeSwitchStmt: list=x.Body.List}; seen:=map[string]bool{}; for _,cc:=range list{ for _,e:=range cc.List{ s:=p.text(e); if seen[s]{ out=append(out,p.diag("dupCase", e.Pos(), fmt.Sprintf("'case %s' is duplicated", s))) }; seen[s]=true } } }); return }
func checkDupSubExpr(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ b,ok:=n.(*ast.BinaryExpr); if !ok{return}; if (b.Op==token.LOR||b.Op==token.LAND||b.Op==token.EQL||b.Op==token.NEQ) && p.text(b.X)==p.text(b.Y){ out=append(out,p.diag("dupSubExpr", b.Pos(), fmt.Sprintf("suspicious identical LHS and RHS for `%s` operator", b.Op.String()))) } }); return }
func checkElseIf(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ ifs,ok:=n.(*ast.IfStmt); if !ok{return}; if b,ok:=ifs.Else.(*ast.BlockStmt); ok && len(b.List)==1{ if _,ok:=b.List[0].(*ast.IfStmt); ok{ out=append(out,p.diag("elseif", ifs.Else.Pos(), "can replace 'else {if cond {}}' with 'else if cond {}'")) } } }); return }
func checkExitAfterDefer(p *parsedFile)(out []diag){ for _,d:=range p.file.Decls{ fn,ok:=d.(*ast.FuncDecl); if !ok||fn.Body==nil{continue}; var def string; ast.Inspect(fn.Body,func(n ast.Node)bool{ if n==nil{return true}; if ds,ok:=n.(*ast.DeferStmt); ok && def==""{ def="defer "+p.text(ds.Call) }; if c,ok:=n.(*ast.CallExpr); ok&&def!=""{ name:=callName(c); if name=="log.Fatal"||name=="log.Fatalf"||name=="os.Exit"{ out=append(out,p.diag("exitAfterDefer", c.Pos(), fmt.Sprintf("%s will exit, and `%s` will not run", name, def))) } }; return true }) }; return }
func checkFlagDeref(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ u,ok:=n.(*ast.UnaryExpr); if !ok||u.Op!=token.MUL{return}; c,ok:=u.X.(*ast.CallExpr); if !ok{return}; name:=callName(c); if strings.HasPrefix(name,"flag.")&& strings.HasSuffix(name,"Var")==false{ base:=strings.TrimPrefix(name,"flag."); out=append(out,p.diag("flagDeref", u.Pos(), fmt.Sprintf("immediate deref in %s is most likely an error; consider using flag.%sVar", p.text(u), base))) } }); return }
func checkFlagName(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ c,ok:=n.(*ast.CallExpr); if !ok||len(c.Args)==0{return}; name:=callName(c); if !strings.HasPrefix(name,"flag.")||strings.HasSuffix(name,"Var"){return}; if s,ok:=strLit(c.Args[0]); ok && s!=strings.TrimSpace(s){ out=append(out,p.diag("flagName", c.Pos(), fmt.Sprintf("flag name %q contains whitespace", s))) } }); return }
func checkIfElseChain(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ ifs,ok:=n.(*ast.IfStmt); if !ok{return}; count:=1; for e:=ifs.Else; e!=nil; { if next,ok:=e.(*ast.IfStmt); ok{ count++; e=next.Else } else { if _,ok:=e.(*ast.BlockStmt); ok{ count++ }; break } }; if count>=3{ out=append(out,p.diag("ifElseChain", ifs.Pos(), "rewrite if-else to switch statement")) } }); return }
func checkMapKey(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ cl,ok:=n.(*ast.CompositeLit); if !ok{return}; for _,elt:=range cl.Elts{ kv,ok:=elt.(*ast.KeyValueExpr); if !ok{return}; if s,ok:=strLit(kv.Key); ok && s!=strings.TrimSpace(s){ out=append(out,p.diag("mapKey", kv.Key.Pos(), fmt.Sprintf("suspicious whitespace in %q key", s))) } } }); return }
func checkNewDeref(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ u,ok:=n.(*ast.UnaryExpr); if !ok||u.Op!=token.MUL{return}; c,ok:=u.X.(*ast.CallExpr); if !ok||!isIdent(c.Fun,"new")||len(c.Args)!=1{return}; typ:=p.text(c.Args[0]); repl:=typ+"{}"; switch typ{case "bool": repl="false"; case "int","int8","int16","int32","int64","uint","uint8","uint16","uint32","uint64","uintptr","byte","rune","float32","float64","complex64","complex128": repl="0"; case "string": repl="\"\""}; out=append(out,p.diag("newDeref", u.Pos(), fmt.Sprintf("replace `%s` with `%s`", p.text(u), repl))) }); return }
func checkOffBy1(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ ix,ok:=n.(*ast.IndexExpr); if !ok{return}; c,ok:=ix.Index.(*ast.CallExpr); if !ok||!isIdent(c.Fun,"len")||len(c.Args)!=1{return}; if p.text(ix.X)==p.text(c.Args[0]){ out=append(out,p.diag("offBy1", ix.Pos(), fmt.Sprintf("index expr always panics; maybe you wanted %s[len(%s)-1]?", p.text(ix.X), p.text(ix.X)))) } }); return }
func checkRegexpMust(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ as,ok:=n.(*ast.AssignStmt); if !ok{return}; for _,r:=range as.Rhs{ c,ok:=r.(*ast.CallExpr); if !ok||len(c.Args)==0{return}; name:=callName(c); if (name=="regexp.Compile"||name=="regexp.CompilePOSIX") { if pat,ok:=strLit(c.Args[0]); ok{ _=pat; out=append(out,p.diag("regexpMust", c.Pos(), fmt.Sprintf("for const patterns like %s, use regexp.Must%s", p.text(c.Args[0]), strings.TrimPrefix(name,"regexp.")))) } } } }); return }
func checkSingleCaseSwitch(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ switch x:=n.(type){case *ast.SwitchStmt: if countCases(x.Body.List)==1{out=append(out,p.diag("singleCaseSwitch",x.Pos(),"should rewrite switch statement to if statement"))}; case *ast.TypeSwitchStmt: if countCases(x.Body.List)==1{out=append(out,p.diag("singleCaseSwitch",x.Pos(),"should rewrite switch statement to if statement"))} } }); return }
func countCases(list []*ast.CaseClause)int{n:=0; for _,cc:=range list{ if cc.List!=nil{n++} }; return n}
func checkSloppyLen(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ b,ok:=n.(*ast.BinaryExpr); if !ok{return}; if c,ok:=b.X.(*ast.CallExpr); ok&&isIdent(c.Fun,"len")&&len(c.Args)==1{ if v,ok:=intLit(b.Y); ok&&v==0&&(b.Op==token.LEQ||b.Op==token.GTR){ op:="=="; if b.Op==token.GTR{op="!="}; out=append(out,p.diag("sloppyLen", b.Pos(), fmt.Sprintf("%s can be %s %s 0", p.text(b), p.text(c), op))) } } }); return }
func checkSloppyTypeAssert(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ ta,ok:=n.(*ast.TypeAssertExpr); if ok && p.text(ta.Type)=="interface{}"{ out=append(out,p.diag("sloppyTypeAssert", ta.Pos(), "type assertion from/to types are identical")) } }); return }
func checkSwitchTrue(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ sw,ok:=n.(*ast.SwitchStmt); if ok && sw.Tag!=nil && p.text(sw.Tag)=="true"{ out=append(out,p.diag("switchTrue", sw.Pos(), "replace 'switch true {}' with 'switch {}'")) } }); return }
func checkTypeSwitchVar(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ ts,ok:=n.(*ast.TypeSwitchStmt); if !ok{return}; if _,ok:=ts.Assign.(*ast.ExprStmt); ok{ c:=countCases(ts.Body.List); word:="cases"; if c==1{word="case"}; out=append(out,p.diag("typeSwitchVar", ts.Pos(), fmt.Sprintf("%d %s can benefit from type switch with assignment", c, word))) } }); return }
func checkUnderef(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ s,ok:=n.(*ast.SelectorExpr); if !ok{return}; par,ok:=s.X.(*ast.ParenExpr); if !ok{return}; u,ok:=par.X.(*ast.UnaryExpr); if !ok||u.Op!=token.MUL{return}; old:=p.text(s); neu:=p.text(u.X)+"."+s.Sel.Name; out=append(out,p.diag("underef", s.Pos(), fmt.Sprintf("could simplify %s to %s", old, neu))) }); return }
func checkUnlambda(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ fl,ok:=n.(*ast.FuncLit); if !ok||fl.Type.Params==nil||len(fl.Body.List)!=1{return}; ret,ok:=fl.Body.List[0].(*ast.ReturnStmt); if !ok||len(ret.Results)!=1{return}; call,ok:=ret.Results[0].(*ast.CallExpr); if !ok{return}; if len(call.Args)!=countParams(fl.Type.Params){return}; out=append(out,p.diag("unlambda", fl.Pos(), fmt.Sprintf("replace `%s` with `%s`", p.text(fl), p.text(call.Fun)))) }); return }
func countParams(fl *ast.FieldList)int{n:=0;if fl==nil{return 0}; for _,f:=range fl.List{ if len(f.Names)==0{n++}else{n+=len(f.Names)} }; return n}
func checkUnslice(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ s,ok:=n.(*ast.SliceExpr); if !ok||s.Low!=nil||s.High!=nil||s.Max!=nil{return}; out=append(out,p.diag("unslice", s.Pos(), fmt.Sprintf("could simplify %s to %s", p.text(s), p.text(s.X)))) }); return }
func checkWrapperFunc(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ c,ok:=n.(*ast.CallExpr); if !ok||len(c.Args)!=1{return}; s,ok:=c.Fun.(*ast.SelectorExpr); if !ok{return}; if s.Sel.Name=="Add"{ if v,ok:=intLit(c.Args[0]); ok&&v==-1{ out=append(out,p.diag("wrapperFunc", c.Pos(), fmt.Sprintf("use WaitGroup.Done method in `%s`", p.text(c)))) } } }); return }

// Lightweight implementations for many optional checkers. These mimic common documented cases.
func checkAppendCombine(p *parsedFile)(out []diag){ return nil }
func checkBadSorting(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ as,ok:=n.(*ast.AssignStmt); if !ok||len(as.Rhs)!=1{return}; c,ok:=as.Rhs[0].(*ast.CallExpr); if ok&&callName(c)=="sort.StringSlice"{out=append(out,p.diag("badSorting",c.Pos(),"use sort.Strings(x) instead of x = sort.StringSlice(x)"))} }); return }
func checkBoolExprSimplify(p *parsedFile)(out []diag){ return nil }
func checkShadow(p *parsedFile,name string)(out []diag){ built:=map[string]bool{"len":true,"cap":true,"new":true,"make":true,"append":true,"copy":true,"delete":true,"panic":true,"print":true,"println":true,"string":true,"int":true,"bool":true,"error":true}; inspect(p,func(n ast.Node){ as,ok:=n.(*ast.AssignStmt); if !ok||as.Tok!=token.DEFINE{return}; for _,e:=range as.Lhs{ if id,ok:=e.(*ast.Ident); ok&&built[id.Name]{ out=append(out,p.diag(name,id.Pos(),fmt.Sprintf("shadowing of predeclared identifier: %s", id.Name))) } } }); return }
func checkCommentedOutImport(p *parsedFile)(out []diag){ for _,cg:=range p.file.Comments{ for _,c:=range cg.List{ if strings.Contains(c.Text,"\"")&&strings.Contains(c.Text,"//") {out=append(out,p.diag("commentedOutImport",c.Pos(),"commented-out import"))} } }; return }
func checkDeferInLoop(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ switch x:=n.(type){case *ast.ForStmt: ast.Inspect(x.Body,func(m ast.Node)bool{if ds,ok:=m.(*ast.DeferStmt);ok{out=append(out,p.diag("deferInLoop",ds.Pos(),"possible resource leak, 'defer' is called in the 'for' loop"))}; return true}); case *ast.RangeStmt: ast.Inspect(x.Body,func(m ast.Node)bool{if ds,ok:=m.(*ast.DeferStmt);ok{out=append(out,p.diag("deferInLoop",ds.Pos(),"possible resource leak, 'defer' is called in the 'for' loop"))}; return true})} }); return }
func checkDeferUnlambda(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ ds,ok:=n.(*ast.DeferStmt); if !ok{return}; if fl,ok:=ds.Call.Fun.(*ast.FuncLit); ok&&len(fl.Body.List)==1{out=append(out,p.diag("deferUnlambda",ds.Pos(),"can replace deferred function literal with direct call"))} }); return }
func checkDocStub(p *parsedFile)(out []diag){ for _,d:=range p.file.Decls{ if fn,ok:=d.(*ast.FuncDecl); ok&&fn.Doc!=nil{ for _,c:=range fn.Doc.List{ if strings.HasSuffix(strings.TrimSpace(c.Text), fn.Name.Name+" ...")||strings.Contains(c.Text, fn.Name.Name+" ...") {out=append(out,p.diag("docStub",c.Pos(),"doc comment is a stub"))} } } }; return }
func checkDupImport(p *parsedFile)(out []diag){ seen:=map[string]token.Pos{}; for _,im:=range p.file.Imports{ path:=im.Path.Value; if pos,ok:=seen[path]; ok{_=pos; out=append(out,p.diag("dupImport",im.Pos(),fmt.Sprintf("%s imported more than once", path)))}; seen[path]=im.Pos() }; return }
func checkDynamicFmtString(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ c,ok:=n.(*ast.CallExpr); if !ok||len(c.Args)==0{return}; name:=callName(c); if (name=="fmt.Errorf"||name=="fmt.Sprintf"||name=="fmt.Printf") { if _,ok:=strLit(c.Args[0]); !ok{out=append(out,p.diag("dynamicFmtString",c.Pos(),"format string is not a string literal"))} } }); return }
func checkEmptyDecl(p *parsedFile)(out []diag){ for _,d:=range p.file.Decls{ if gd,ok:=d.(*ast.GenDecl); ok&&len(gd.Specs)==0{out=append(out,p.diag("emptyDecl",gd.Pos(),"empty declaration block"))} }; return }
func checkEmptyStringTest(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ b,ok:=n.(*ast.BinaryExpr); if !ok{return}; if c,ok:=b.X.(*ast.CallExpr); ok&&isIdent(c.Fun,"len")&&len(c.Args)==1{ if v,ok:=intLit(b.Y); ok&&v==0&&(b.Op==token.EQL||b.Op==token.NEQ){ out=append(out,p.diag("emptyStringTest",b.Pos(),"replace len(s) comparison with s comparison to empty string")) } } }); return }
func checkEqualFold(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ b,ok:=n.(*ast.BinaryExpr); if ok&&(b.Op==token.EQL||b.Op==token.NEQ)&&strings.Contains(p.text(b),"strings.ToLower"){out=append(out,p.diag("equalFold",b.Pos(),"consider using strings.EqualFold"))} }); return }
func checkExternalErrorReassign(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ as,ok:=n.(*ast.AssignStmt); if ok&&len(as.Lhs)>0{ if s,ok:=as.Lhs[0].(*ast.SelectorExpr); ok&&as.Tok==token.ASSIGN{out=append(out,p.diag("externalErrorReassign",s.Pos(),"reassignment of external package variable"))} } }); return }
func checkFilepathJoin(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ c,ok:=n.(*ast.CallExpr); if !ok||callName(c)!="filepath.Join"{return}; for _,a:=range c.Args{ if s,ok:=strLit(a); ok&&(strings.HasSuffix(s,"/")||strings.HasPrefix(s,"/")){out=append(out,p.diag("filepathJoin",a.Pos(),"filepath.Join argument contains path separator"))} } }); return }
func checkHexLiteral(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ bl,ok:=n.(*ast.BasicLit); if ok&&bl.Kind==token.INT&&(strings.HasPrefix(bl.Value,"0X")||mixedHex(bl.Value)){out=append(out,p.diag("hexLiteral",bl.Pos(),"hex literal has mixed-case digits"))} }); return }
func mixedHex(s string)bool{ if !strings.HasPrefix(strings.ToLower(s),"0x"){return false}; hasL,hasU:=false,false; for _,r:=range s[2:]{ if r>='a'&&r<='f'{hasL=true}; if r>='A'&&r<='F'{hasU=true} }; return hasL&&hasU }
func checkHTTPNoBody(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ c,ok:=n.(*ast.CallExpr); if ok&&callName(c)=="http.NewRequest"&&len(c.Args)>=3&&p.text(c.Args[2])=="nil"{out=append(out,p.diag("httpNoBody",c.Args[2].Pos(),"use http.NoBody instead of nil"))} }); return }
