func checkReturnAfterHTTPError(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ ifs,ok:=n.(*ast.IfStmt); if !ok||ifs.Body==nil{return}; hasErr,hasRet:=false,false; for _,st:=range ifs.Body.List{ if es,ok:=st.(*ast.ExprStmt); ok{ if c,ok:=es.X.(*ast.CallExpr); ok&&callName(c)=="http.Error"{hasErr=true} }; if _,ok:=st.(*ast.ReturnStmt); ok{hasRet=true} }; if hasErr&&!hasRet{out=append(out,p.diag("returnAfterHttpError",ifs.Pos(),"http.Error call should be followed by return"))} }); return }
