func checkYoda(p *parsedFile)(out []diag){ inspect(p,func(n ast.Node){ b,ok:=n.(*ast.BinaryExpr); if ok&&(b.Op==token.EQL||b.Op==token.NEQ){ if _,ok:=b.X.(*ast.BasicLit); ok{out=append(out,p.diag("yodaStyleExpr",b.Pos(),"use constant on the right side of the expression"))}; if p.text(b.X)=="nil"{out=append(out,p.diag("yodaStyleExpr",b.Pos(),"use constant on the right side of the expression"))} } }); return }
